'use client'

import { forwardRef, useEffect, useId, useRef, useState, type InputHTMLAttributes } from 'react'
import { motion, useMotionValue, useReducedMotion, useSpring } from 'motion/react'
import { cn } from '@/lib/utils'
import { playHoverSound, playClickSound } from '@/lib/sound'

const EYE_OPEN_TOP = 'M1 12 C1 12 5 4 12 4 C19 4 23 12 23 12'
const EYE_CLOSED_TOP = 'M1 12 C1 12 5 12 12 12 C19 12 23 12 23 12'
const EYE_OPEN_BOTTOM = 'M1 12 C1 12 5 20 12 20 C19 20 23 12 23 12'
const EYE_CLOSED_BOTTOM = 'M1 12 C1 12 5 12 12 12 C19 12 23 12 23 12'
const CLIP_OPEN = 'M1 12 C1 12 5 4 12 4 C19 4 23 12 23 12 C23 12 19 20 12 20 C5 20 1 12 1 12Z'
const CLIP_CLOSED = 'M1 12 C1 12 5 12 12 12 C19 12 23 12 23 12 C23 12 19 12 12 12 C5 12 1 12 1 12Z'

const PUPIL_RX = 5
const PUPIL_RY = 3.5

export interface PasswordInputProps extends Omit<InputHTMLAttributes<HTMLInputElement>, 'type'> {
  label?: string
  showLabel?: string
  hideLabel?: string
  containerClassName?: string
  labelClassName?: string
}

export const PasswordInput = forwardRef<HTMLInputElement, PasswordInputProps>(
  (
    {
      label = 'Password',
      showLabel = 'Show password',
      hideLabel = 'Hide password',
      containerClassName,
      labelClassName,
      className,
      id: idProp,
      ...props
    },
    ref,
  ) => {
    const [visible, setVisible] = useState(false)
    const [blinking, setBlinking] = useState(false)
    const eyeRef = useRef<SVGSVGElement | null>(null)
    const reactId = useId()
    const id = idProp ?? reactId
    const prefersReducedMotion = useReducedMotion()

    const px = useMotionValue(0)
    const py = useMotionValue(0)
    const sx = useSpring(px, { stiffness: 350, damping: 28, mass: 0.4 })
    const sy = useSpring(py, { stiffness: 350, damping: 28, mass: 0.4 })

    useEffect(() => {
      if (typeof window === 'undefined' || prefersReducedMotion) return
      const handle = (e: MouseEvent) => {
        const el = eyeRef.current
        if (!el) return
        const rect = el.getBoundingClientRect()
        const cx = rect.left + rect.width / 2
        const cy = rect.top + rect.height / 2
        const dx = e.clientX - cx
        const dy = e.clientY - cy
        const dist = Math.hypot(dx, dy) || 1
        const nx = dx / dist
        const ny = dy / dist
        const reach = Math.min(1, dist / 240)
        px.set(nx * PUPIL_RX * reach)
        py.set(ny * PUPIL_RY * reach)
      }
      window.addEventListener('mousemove', handle)
      return () => window.removeEventListener('mousemove', handle)
    }, [px, py, prefersReducedMotion])

    useEffect(() => {
      if (prefersReducedMotion) return
      let timer: ReturnType<typeof setTimeout>
      let blinkTimer: ReturnType<typeof setTimeout>
      const schedule = () => {
        const next = 2000 + Math.random() * 4000
        timer = setTimeout(() => {
          setBlinking(true)
          blinkTimer = setTimeout(() => setBlinking(false), 120)
          schedule()
        }, next)
      }
      schedule()
      return () => {
        clearTimeout(timer)
        clearTimeout(blinkTimer)
      }
    }, [prefersReducedMotion])

    const closed = blinking || visible
    const transition = prefersReducedMotion
      ? { duration: 0 }
      : { duration: 0.14, ease: [0.22, 1, 0.36, 1] as const }

    return (
      <div className={cn('w-72', containerClassName)} data-state={visible ? 'visible' : 'hidden'}>
        {label ? (
          <label
            htmlFor={id}
            className={cn('mb-2 block font-normal text-sm font-sans', labelClassName)}
            style={{ color: 'var(--color-fg)' }}
          >
            {label}
          </label>
        ) : null}
        <div className="relative">
          <input
            ref={ref}
            id={id}
            type={visible ? 'text' : 'password'}
            className={cn(
              'h-11 w-full rounded-md ps-3.5 pe-12 py-2.5 text-sm outline-none',
              'border border-(--color-border)',
              'focus-visible:ring-2 focus-visible:ring-(--color-accent) focus-visible:ring-offset-1 focus-visible:ring-offset-(--color-bg)',
              'transition-[border-color,box-shadow] duration-(--motion-dur-fast) motion-reduce:transition-none',
              'placeholder:text-(--color-subtle)',
              className,
            )}
            style={{
              backgroundColor: 'var(--color-surface-2)',
              color: 'var(--color-fg)',
            }}
            {...props}
          />
          <button
            type="button"
            onMouseEnter={() => playHoverSound()}
            onClick={() => {
              playClickSound()
              setVisible((v) => !v)
            }}
            aria-label={visible ? hideLabel : showLabel}
            aria-pressed={visible}
            data-state={visible ? 'visible' : 'hidden'}
            className={cn(
              'absolute inset-e-3 top-1/2 -translate-y-1/2 cursor-pointer text-(--color-muted)',
              "before:content-[''] before:absolute before:top-1/2 before:start-1/2 before:-translate-x-1/2 rtl:before:translate-x-1/2 before:-translate-y-1/2 before:size-11",
              'transition-[color,transform] duration-(--motion-dur-fast) motion-reduce:transition-none motion-reduce:transform-none',
              'hover:text-(--color-fg) active:scale-90',
              'focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-(--color-accent) focus-visible:rounded-md',
            )}
          >
            <svg
              ref={eyeRef}
              className="h-5 w-5"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth="1.7"
              strokeLinecap="round"
              strokeLinejoin="round"
              aria-hidden="true"
            >
              <defs>
                <clipPath id={`${id}-eye-clip`}>
                  <motion.path
                    d={CLIP_OPEN}
                    animate={{ d: closed ? CLIP_CLOSED : CLIP_OPEN }}
                    transition={transition}
                  />
                </clipPath>
              </defs>
              <motion.path
                d={EYE_OPEN_TOP}
                animate={{ d: closed ? EYE_CLOSED_TOP : EYE_OPEN_TOP }}
                transition={transition}
              />
              <motion.path
                d={EYE_OPEN_BOTTOM}
                animate={{ d: closed ? EYE_CLOSED_BOTTOM : EYE_OPEN_BOTTOM }}
                transition={transition}
              />
              <g clipPath={`url(#${id}-eye-clip)`}>
                <motion.g style={{ x: sx, y: sy }}>
                  <circle cx="12" cy="12" r="3" fill="currentColor" stroke="none" />
                </motion.g>
              </g>
            </svg>
          </button>
        </div>
      </div>
    )
  },
)

PasswordInput.displayName = 'PasswordInput'

export function PasswordInputPreview() {
  return <PasswordInput />
}

'use client'

const MUTE_KEY = 'sound-muted'
const MUTE_EVENT = 'sound-mute-change'

let muted = false
if (typeof window !== 'undefined') {
  try {
    muted = localStorage.getItem(MUTE_KEY) === '1'
  } catch {}
}

export function isSoundMuted(): boolean {
  return muted
}

export function setSoundMuted(value: boolean) {
  muted = value
  if (typeof window !== 'undefined') {
    try {
      localStorage.setItem(MUTE_KEY, value ? '1' : '0')
    } catch {}
    window.dispatchEvent(new CustomEvent(MUTE_EVENT))
  }
}

export function toggleSoundMuted(): boolean {
  setSoundMuted(!muted)
  return muted
}

export function subscribeSoundMuted(callback: () => void) {
  if (typeof window === 'undefined') return () => {}
  window.addEventListener(MUTE_EVENT, callback)
  const onStorage = (e: StorageEvent) => {
    if (e.key === MUTE_KEY) callback()
  }
  window.addEventListener('storage', onStorage)
  return () => {
    window.removeEventListener(MUTE_EVENT, callback)
    window.removeEventListener('storage', onStorage)
  }
}

let audioCtx: AudioContext | null = null

function initAudio(): AudioContext | null {
  if (typeof window === 'undefined') return null
  if (!audioCtx) {
    const AudioContextClass =
      window.AudioContext ||
      (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext
    if (AudioContextClass) {
      audioCtx = new AudioContextClass()
    }
  }
  if (audioCtx && audioCtx.state === 'suspended') {
    audioCtx.resume().catch(() => {})
  }
  return audioCtx
}

if (typeof window !== 'undefined') {
  const unlock = () => {
    initAudio()
    window.removeEventListener('pointerdown', unlock)
    window.removeEventListener('keydown', unlock)
    window.removeEventListener('touchstart', unlock)
  }
  window.addEventListener('pointerdown', unlock, { passive: true })
  window.addEventListener('keydown', unlock, { passive: true })
  window.addEventListener('touchstart', unlock, { passive: true })
}

export function getAudioContext(): AudioContext | null {
  return initAudio()
}

export function playHoverSound(volume = 0.12, pitch = 1.2) {
  if (muted) return
  try {
    const ctx = getAudioContext()
    if (!ctx) return
    const now = ctx.currentTime

    const osc = ctx.createOscillator()
    const gain = ctx.createGain()

    osc.type = 'sine'
    osc.frequency.setValueAtTime(1400 * pitch, now)
    osc.frequency.exponentialRampToValueAtTime(350 * pitch, now + 0.012)

    gain.gain.setValueAtTime(volume, now)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.012)

    osc.connect(gain)
    gain.connect(ctx.destination)

    osc.start(now)
    osc.stop(now + 0.012)
  } catch {}
}

export function playClickSound(volume = 0.2, pitch = 1.0) {
  if (muted) return
  try {
    const ctx = getAudioContext()
    if (!ctx) return
    const now = ctx.currentTime

    const osc = ctx.createOscillator()
    const gain = ctx.createGain()

    osc.type = 'triangle'
    osc.frequency.setValueAtTime(850 * pitch, now)
    osc.frequency.exponentialRampToValueAtTime(160 * pitch, now + 0.02)

    gain.gain.setValueAtTime(volume, now)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.02)

    osc.connect(gain)
    gain.connect(ctx.destination)

    osc.start(now)
    osc.stop(now + 0.02)
  } catch {}
}

export function playTickSound(volume = 0.1, pitch = 1.5) {
  if (muted) return
  try {
    const ctx = getAudioContext()
    if (!ctx) return
    const now = ctx.currentTime

    const osc = ctx.createOscillator()
    const gain = ctx.createGain()

    osc.type = 'sine'
    osc.frequency.setValueAtTime(1800 * pitch, now)
    osc.frequency.exponentialRampToValueAtTime(450 * pitch, now + 0.01)

    gain.gain.setValueAtTime(volume, now)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.01)

    osc.connect(gain)
    gain.connect(ctx.destination)

    osc.start(now)
    osc.stop(now + 0.01)
  } catch {}
}

export function playTileNote(frequency = 440, volume = 0.08) {
  if (muted) return
  try {
    const ctx = getAudioContext()
    if (!ctx) return
    const now = ctx.currentTime
    const dur = 1.1

    const osc = ctx.createOscillator()
    const shimmer = ctx.createOscillator()
    const shimmerGain = ctx.createGain()
    const gain = ctx.createGain()

    osc.type = 'sine'
    osc.frequency.setValueAtTime(frequency, now)
    shimmer.type = 'sine'
    shimmer.frequency.setValueAtTime(frequency * 2, now)

    shimmerGain.gain.setValueAtTime(0.22, now)
    shimmerGain.gain.exponentialRampToValueAtTime(0.0001, now + dur * 0.5)

    gain.gain.setValueAtTime(0.0001, now)
    gain.gain.exponentialRampToValueAtTime(volume, now + 0.015)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + dur)

    shimmer.connect(shimmerGain)
    shimmerGain.connect(gain)
    osc.connect(gain)
    gain.connect(ctx.destination)

    osc.start(now)
    osc.stop(now + dur)
    shimmer.start(now)
    shimmer.stop(now + dur)
  } catch {}
}

export function playBounceSound(volume = 0.3, pitch = 1.0) {
  try {
    const ctx = getAudioContext()
    if (!ctx) return
    const now = ctx.currentTime

    const osc = ctx.createOscillator()
    const gain = ctx.createGain()

    osc.type = 'sine'
    osc.frequency.setValueAtTime(260 * pitch, now)
    osc.frequency.exponentialRampToValueAtTime(650 * pitch, now + 0.04)
    osc.frequency.exponentialRampToValueAtTime(190 * pitch, now + 0.14)

    gain.gain.setValueAtTime(volume, now)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.14)

    osc.connect(gain)
    gain.connect(ctx.destination)

    osc.start(now)
    osc.stop(now + 0.14)

    const subOsc = ctx.createOscillator()
    const subGain = ctx.createGain()

    subOsc.type = 'triangle'
    subOsc.frequency.setValueAtTime(420 * pitch, now)
    subOsc.frequency.exponentialRampToValueAtTime(120 * pitch, now + 0.05)

    subGain.gain.setValueAtTime(volume * 0.7, now)
    subGain.gain.exponentialRampToValueAtTime(0.0001, now + 0.05)

    subOsc.connect(subGain)
    subGain.connect(ctx.destination)

    subOsc.start(now)
    subOsc.stop(now + 0.05)
  } catch {}
}
